    Bug 2050347 - Also refresh the password of Exchange incoming servers when the auth method is NTLM. r=jtracey

    Differential Revision: https://phabricator.services.mozilla.com/D309340

diff --git a/mailnews/protocols/exchange/src/ExchangeIncomingServer.cpp b/mailnews/protocols/exchange/src/ExchangeIncomingServer.cpp
index 4fcee6d64af..8120dbd1165 100644
--- a/mailnews/protocols/exchange/src/ExchangeIncomingServer.cpp
+++ b/mailnews/protocols/exchange/src/ExchangeIncomingServer.cpp
@@ -544,7 +544,8 @@ NS_IMETHODIMP ExchangeIncomingServer::GetPassword(nsAString& password) {
   // takes care of updating `m_password`.
   nsAutoCString value;
   MOZ_TRY(mPasswordModule->GetCachedPassword(value));
-  if (value.IsEmpty() && authMethod == nsMsgAuthMethod::passwordCleartext) {
+  if (value.IsEmpty() && (authMethod == nsMsgAuthMethod::passwordCleartext ||
+                          authMethod == nsMsgAuthMethod::NTLM)) {
     MOZ_TRY(GetPasswordWithoutUI());
   }
